    public sealed class SoldierEquipmentTests
    {
        [Test]public void SoldierId_IsTypedStableAndDuplicateRejected(){var c=Context();var s=AcquireDeli(c);Assert.That(s.Id.Value,Is.EqualTo("soldier-1"));Assert.Throws<InvalidOperationException>(()=>AcquireDeli(c));Assert.That(typeof(SoldierId),Is.Not.EqualTo(typeof(CharacterId)));}
        [Test]public void SoldierRoster_IsCanonicalAndCannotExceedAggregateHeadcount(){var c=Context(headcount:2);AcquireDeli(c,"soldier-b","b-");AcquireDeli(c,"soldier-a","a-");Assert.That(c.Runtime.Soldiers.Soldiers.OrderedSoldiers.Select(x=>x.Id.Value),Is.EqualTo(new[]{"soldier-a","soldier-b"}));Assert.Throws<InvalidOperationException>(()=>AcquireDeli(c,"soldier-c","c-"));Assert.That(c.Unit.Headcount,Is.EqualTo(2));}
        [Test]public void InvalidUnitOrRecruitmentProvenance_IsRejectedWithoutStockMutation(){var c=Context();var before=c.Market.Stock.QuantityOf(c.WeaponGood);Assert.Throws<System.Collections.Generic.KeyNotFoundException>(()=>c.Service.AcquireFromCity(DeliRequest("s",UnitGroupId.Create("missing"),c.Record.Id,"x-"),T(0)));Assert.Throws<System.Collections.Generic.KeyNotFoundException>(()=>c.Service.AcquireFromCity(DeliRequest("s",c.Unit.Id,RecruitmentRecordId.Create("missing"),"y-"),T(0)));Assert.That(c.Market.Stock.QuantityOf(c.WeaponGood),Is.EqualTo(before));}
        [Test]public void Acquisition_ConsumesRealCityGoodsAndCreatesPersistentOwnedEquipment(){var c=Context();var beforeWeapon=c.Market.Stock.QuantityOf(c.WeaponGood);var beforeMount=c.Market.Stock.QuantityOf(c.MountGood);var s=AcquireDeli(c);Assert.That(c.Market.Stock.QuantityOf(c.WeaponGood),Is.EqualTo(beforeWeapon-2));Assert.That(c.Market.Stock.QuantityOf(c.MountGood),Is.EqualTo(beforeMount-1));Assert.That(c.Runtime.Soldiers.Equipment.OrderedEquipment.Count,Is.EqualTo(3));Assert.That(c.Runtime.Soldiers.Equipment.OrderedEquipment.All(x=>x.Owner.Equals(EquipmentOwnerRef.Soldier(s.Id))),Is.True);}
        [Test]public void SameSeedStateAndAcquisitionCommand_ProduceIdenticalPersistentOutcome(){var a=Context();var b=Context();var beforeA=a.Runtime.Random.CaptureState();var beforeB=b.Runtime.Random.CaptureState();var soldierA=AcquireDeli(a);var soldierB=AcquireDeli(b);var serializer=new CampaignSaveTextSerializer();Assert.That(serializer.Serialize(CampaignSaveMapper.ToSaveData(a.Runtime)),Is.EqualTo(serializer.Serialize(CampaignSaveMapper.ToSaveData(b.Runtime))));Assert.That(soldierA.Loadout.OrderedWeapons.Select(x=>x.EquipmentId.Value),Is.EqualTo(soldierB.Loadout.OrderedWeapons.Select(x=>x.EquipmentId.Value)));Assert.That(a.Runtime.Random.CaptureState().State,Is.EqualTo(beforeA.State));Assert.That(b.Runtime.Random.CaptureState().State,Is.EqualTo(beforeB.State));}
        [Test]public void AcquisitionFailure_IsAtomic(){var c=Context();c.Market.Stock.Remove(c.MountGood,c.Market.Stock.QuantityOf(c.MountGood));var weapon=c.Market.Stock.QuantityOf(c.WeaponGood);Assert.Throws<InvalidOperationException>(()=>AcquireDeli(c));Assert.That(c.Market.Stock.QuantityOf(c.WeaponGood),Is.EqualTo(weapon));Assert.That(c.Runtime.Soldiers.Equipment.OrderedEquipment,Is.Empty);Assert.That(c.Runtime.Soldiers.Soldiers.OrderedSoldiers,Is.Empty);}
        [Test]public void LoadoutSupportsAllAuthoritativeWeaponSlotsAndArmorLayers(){Assert.That(Enum.GetNames(typeof(WeaponSlot)),Is.EquivalentTo(new[]{"Main","Secondary","Sidearm","Throwing","Ammo","Special"}));Assert.That(Enum.GetNames(typeof(ArmorSlot)),Is.EquivalentTo(new[]{"Inner","Body","Additional","Head","Limbs","MountArmor"}));}
        [Test]public void AttackModeAndDamageType_AreSeparateAndAuthoritative(){Assert.That(typeof(AttackMode),Is.Not.EqualTo(typeof(DamageType)));Assert.That(Enum.GetNames(typeof(DamageType)),Is.EquivalentTo(new[]{"Cut","Pierce","Blunt"}));Assert.That(Enum.GetNames(typeof(AttackMode)),Is.EquivalentTo(new[]{"Thrust","Slash","Crush"}));}
        [Test]public void WeaponPreservesMultipleAttackOptions(){var c=Context();var lance=c.Runtime.Soldiers.Definitions.GetRequired(WeaponDefinitionId.Create("lance"));Assert.That(lance.AttackOptions.Select(x=>x.Mode),Is.EquivalentTo(new[]{AttackMode.Thrust,AttackMode.Crush}));Assert.That(lance.AttackOptions.Select(x=>x.DamageType),Does.Contain(DamageType.Pierce));}
        [Test]public void WrongWeaponSlot_IsRejectedWithoutGoodsMutation(){var c=Context();var before=c.Market.Stock.QuantityOf(c.WeaponGood);var request=new SoldierAcquisitionRequest(SoldierId.Create("bad"),c.Unit.Id,TroopDefinitionId.Create("deli"),c.Record.Id,CityId.Create("city-home"),new[]{EquipmentIssueLine.Weapon(EquipmentInstanceId.Create("bad-lance"),WeaponDefinitionId.Create("lance"),WeaponSlot.Sidearm),EquipmentIssueLine.Mount(EquipmentInstanceId.Create("bad-mount"),MountDefinitionId.Create("fast-mount"))});Assert.Throws<InvalidOperationException>(()=>c.Service.AcquireFromCity(request,T(0)));Assert.That(c.Market.Stock.QuantityOf(c.WeaponGood),Is.EqualTo(before));}
        [Test]public void ArmorCannotOccupyWeaponSlot_ByTypedConstructionBoundary(){Assert.That(typeof(EquipmentIssueLine).GetConstructors(BindingFlags.Public|BindingFlags.Instance),Is.Empty);Assert.That(typeof(EquipmentIssueLine).GetMethod("Weapon")!.GetParameters()[1].ParameterType,Is.EqualTo(typeof(WeaponDefinitionId)));Assert.That(typeof(EquipmentIssueLine).GetMethod("Armor")!.GetParameters()[1].ParameterType,Is.EqualTo(typeof(ArmorDefinitionId)));}
        [Test]public void RangedWeaponRequiresMatchingAmmoFamily(){var c=Context("humbaraci");var badAmmo=new AuxiliaryEquipmentDefinition(AuxiliaryEquipmentDefinitionId.Create("wrong-ammo"),"Wrong",AuxiliaryEquipmentKind.Ammunition,c.AmmoGood,V("wrong-ammo"),AmmoFamilyId.Create("arrows"));c.Runtime.Soldiers.Definitions.Add(badAmmo);var before=c.Market.Stock.QuantityOf(c.WeaponGood);var lines=new[]{EquipmentIssueLine.Weapon(E("musket-i"),WeaponDefinitionId.Create("musket"),WeaponSlot.Main),EquipmentIssueLine.Auxiliary(E("ammo-i"),badAmmo.Id,WeaponSlot.Ammo),EquipmentIssueLine.Auxiliary(E("humbara-i"),AuxiliaryEquipmentDefinitionId.Create("humbara"),WeaponSlot.Special),EquipmentIssueLine.Weapon(E("yatagan-i"),WeaponDefinitionId.Create("yatagan"),WeaponSlot.Sidearm)};Assert.Throws<InvalidOperationException>(()=>c.Service.AcquireFromCity(Request(c,"humbaraci",lines),T(0)));Assert.That(c.Market.Stock.QuantityOf(c.WeaponGood),Is.EqualTo(before));}
        [Test]public void RangedWeaponWithMatchingAmmoAndSpecialSlot_IsRepresentable(){var c=Context("humbaraci");var lines=new[]{EquipmentIssueLine.Weapon(E("musket-i"),WeaponDefinitionId.Create("musket"),WeaponSlot.Main),EquipmentIssueLine.Auxiliary(E("ammo-i"),AuxiliaryEquipmentDefinitionId.Create("shot"),WeaponSlot.Ammo),EquipmentIssueLine.Auxiliary(E("humbara-i"),AuxiliaryEquipmentDefinitionId.Create("humbara"),WeaponSlot.Special),EquipmentIssueLine.Weapon(E("yatagan-i"),WeaponDefinitionId.Create("yatagan"),WeaponSlot.Sidearm)};var s=c.Service.AcquireFromCity(Request(c,"humbaraci",lines),T(0));Assert.That(s.Loadout.WeaponAt(WeaponSlot.Ammo),Is.Not.Null);Assert.That(s.Loadout.WeaponAt(WeaponSlot.Special),Is.Not.Null);}
        [Test]public void InfantryTroopRejectsMount(){var c=Context("humbaraci");var lines=new[]{EquipmentIssueLine.Mount(E("mount"),MountDefinitionId.Create("fast-mount"))};Assert.Throws<InvalidOperationException>(()=>c.Service.AcquireFromCity(Request(c,"humbaraci",lines),T(0)));}
        [Test]public void MountedTroopRequiresMount(){var c=Context();var lines=new[]{EquipmentIssueLine.Weapon(E("lance"),WeaponDefinitionId.Create("lance"),WeaponSlot.Main)};Assert.Throws<InvalidOperationException>(()=>c.Service.AcquireFromCity(Request(c,"deli",lines),T(0)));}
        [Test]public void MountArmorCannotExistWithoutMount(){var c=Context("bostanci");var lines=new[]{EquipmentIssueLine.Armor(E("horse-armor"),ArmorDefinitionId.Create("mount-armor"),ArmorSlot.MountArmor)};Assert.Throws<InvalidOperationException>(()=>c.Service.AcquireFromCity(Request(c,"bostanci",lines),T(0)));}
        [Test]public void ContentDrivenUnarmoredTroopRejectsArmor(){var c=Context();var lines=DeliLines("a-").Concat(new[]{EquipmentIssueLine.Armor(E("body"),ArmorDefinitionId.Create("body-armor"),ArmorSlot.Body)});Assert.Throws<InvalidOperationException>(()=>c.Service.AcquireFromCity(Request(c,"deli",lines),T(0)));}
        [Test]public void PersistentLoadoutQueriesNeverRerollOrConsumeRng(){var c=Context();var s=AcquireDeli(c);var before=c.Runtime.Random.CaptureState();var first=c.Service.ReadPersistentLoadout(s.Id);for(var i=0;i<10;i++)Assert.That(c.Service.ReadPersistentLoadout(s.Id),Is.SameAs(first));var snapshot=new SoldierCombatSnapshot(s);var after=c.Runtime.Random.CaptureState();Assert.That(snapshot.Loadout,Is.SameAs(first));Assert.That(after.State,Is.EqualTo(before.State));Assert.That(after.DrawCount,Is.EqualTo(before.DrawCount));}
        [Test]public void LoadoutCanChangeOnlyThroughExplicitServiceMutation(){var c=Context();var s=AcquireDeli(c);Assert.That(typeof(SoldierInstance).GetProperty("Loadout")!.SetMethod!.IsPrivate,Is.True);var replacement=new SoldierLoadout(new[]{new WeaponSlotAssignment(WeaponSlot.Main,E("eq-lance")),new WeaponSlotAssignment(WeaponSlot.Secondary,E("eq-sword"))},mount:E("eq-mount"));c.Service.ReplaceLoadout(s.Id,replacement);Assert.That(s.Loadout.WeaponAt(WeaponSlot.Secondary)!.Value.Value,Is.EqualTo("eq-sword"));Assert.That(s.Loadout.WeaponAt(WeaponSlot.Sidearm),Is.Null);}
        [Test]public void WeaponDefinitionEquipmentInstanceTradeGoodAndSupplyRemainDistinct(){Assert.That(typeof(WeaponDefinition),Is.Not.EqualTo(typeof(EquipmentInstance)));Assert.That(typeof(WeaponDefinitionId),Is.Not.EqualTo(typeof(TradeGoodId)));Assert.That(typeof(SoldierLoadout).GetProperties().Any(x=>x.PropertyType==typeof(ArmySupplyInventory)),Is.False);}
        [Test]public void MilitaryCliqueCannotOwnSoldierOrEquipment(){Assert.That(Enum.GetNames(typeof(EquipmentOwnerKind)),Does.Not.Contain("Clique"));Assert.That(typeof(EquipmentOwnerRef).GetMethods().Select(x=>x.Name),Does.Not.Contain("Clique"));Assert.That(typeof(SoldierInstance).GetProperties().Any(x=>x.Name.Contains("Clique")||x.Name.Contains("CombatBonus")),Is.False);}
        [Test]public void HistoricalFixturesUseGenericDefinitionsWithoutNameSpecificCode(){var c=Context();var defs=c.Runtime.Soldiers.Definitions;var deli=defs.GetRequired(TroopDefinitionId.Create("deli"));var hum=defs.GetRequired(TroopDefinitionId.Create("humbaraci"));var bost=defs.GetRequired(TroopDefinitionId.Create("bostanci"));Assert.That(deli.MountContext,Is.EqualTo(MountContext.MountedOnly));Assert.That(deli.AllowsArmor,Is.False);Assert.That(hum.AllowedWeaponFamilies,Does.Contain(WeaponFamily.Grenade));Assert.That(hum.AllowsArmor,Is.False);Assert.That(bost.UnitClassId.Value,Is.EqualTo("imperial-guard-service"));Assert.That(bost.AllowsArmor,Is.True);Assert.That(typeof(SoldierEquipmentService).GetMethods().Any(x=>x.Name.Contains("Deli")||x.Name.Contains("Humbar")||x.Name.Contains("Bostan")),Is.False);}
        [Test]public void EveryWeaponSlotShieldAndGameplayArmorLayerCanBeIssuedThroughGenericContracts(){var c=Context("slot-test");var lines=new[]{EquipmentIssueLine.Weapon(E("polearm-i"),WeaponDefinitionId.Create("polearm"),WeaponSlot.Main),EquipmentIssueLine.Weapon(E("pistol-i"),WeaponDefinitionId.Create("pistol"),WeaponSlot.Secondary),EquipmentIssueLine.Weapon(E("yatagan-i"),WeaponDefinitionId.Create("yatagan"),WeaponSlot.Sidearm),EquipmentIssueLine.Weapon(E("javelin-i"),WeaponDefinitionId.Create("javelin"),WeaponSlot.Throwing),EquipmentIssueLine.Auxiliary(E("shot-i"),AuxiliaryEquipmentDefinitionId.Create("shot"),WeaponSlot.Ammo),EquipmentIssueLine.Auxiliary(E("special-i"),AuxiliaryEquipmentDefinitionId.Create("humbara"),WeaponSlot.Special),EquipmentIssueLine.Armor(E("inner-i"),ArmorDefinitionId.Create("inner-armor"),ArmorSlot.Inner),EquipmentIssueLine.Armor(E("body-i"),ArmorDefinitionId.Create("body-armor"),ArmorSlot.Body),EquipmentIssueLine.Armor(E("extra-i"),ArmorDefinitionId.Create("extra-armor"),ArmorSlot.Additional),EquipmentIssueLine.Armor(E("head-i"),ArmorDefinitionId.Create("head-armor"),ArmorSlot.Head),EquipmentIssueLine.Armor(E("limb-i"),ArmorDefinitionId.Create("limb-armor"),ArmorSlot.Limbs),EquipmentIssueLine.Shield(E("shield-i"),ShieldDefinitionId.Create("shield"))};var soldier=c.Service.AcquireFromCity(Request(c,"slot-test",lines),T(0));Assert.That(soldier.Loadout.OrderedWeapons.Select(x=>x.Slot),Is.EquivalentTo(Enum.GetValues(typeof(WeaponSlot)).Cast<WeaponSlot>()));Assert.That(soldier.Loadout.OrderedArmor.Select(x=>x.Slot),Is.EquivalentTo(new[]{ArmorSlot.Inner,ArmorSlot.Body,ArmorSlot.Additional,ArmorSlot.Head,ArmorSlot.Limbs}));Assert.That(soldier.Loadout.Shield,Is.Not.Null);}
        [Test]public void MountArmorIsSeparateAndValidOnlyWithMount(){var c=Context("mounted-armored");var lines=new[]{EquipmentIssueLine.Mount(E("mount-i"),MountDefinitionId.Create("fast-mount")),EquipmentIssueLine.Armor(E("mount-armor-i"),ArmorDefinitionId.Create("mount-armor"),ArmorSlot.MountArmor)};var soldier=c.Service.AcquireFromCity(Request(c,"mounted-armored",lines),T(0));Assert.That(soldier.Loadout.Mount,Is.Not.Null);Assert.That(soldier.Loadout.ArmorAt(ArmorSlot.MountArmor),Is.Not.Null);Assert.That(soldier.Loadout.ArmorAt(ArmorSlot.Body),Is.Null);}
        [Test]public void UnitClassAndCombatRoleAreSeparateTypedContentReferences(){var c=Context();var d=c.Runtime.Soldiers.Definitions.GetRequired(TroopDefinitionId.Create("deli"));Assert.That(typeof(UnitClassId),Is.Not.EqualTo(typeof(CombatRoleId)));Assert.That(d.UnitClassId.Value,Is.EqualTo("light-cavalry"));Assert.That(d.DefaultCombatRoleId.Value,Is.EqualTo("shock-cavalry"));}
        [Test]public void SchemaNineRoundTripPreservesSoldierDefinitionsEquipmentAndExactLoadout(){var c=Context();var soldier=AcquireDeli(c);var serializer=new CampaignSaveTextSerializer();var text=serializer.Serialize(CampaignSaveMapper.ToSaveData(c.Runtime));var read=serializer.Deserialize(text);Assert.That(read.Success,Is.True,read.Error);Assert.That(new CampaignSaveValidator().Validate(read.Data!).IsValid,Is.True);var restored=CampaignSaveMapper.ToRuntimeState(read.Data!);var actual=restored.Soldiers.Soldiers.GetRequired(soldier.Id);Assert.That(actual.UnitGroupId,Is.EqualTo(soldier.UnitGroupId));Assert.That(actual.Recruitment.RecordId,Is.EqualTo(soldier.Recruitment.RecordId));Assert.That(actual.Loadout.WeaponAt(WeaponSlot.Main),Is.EqualTo(soldier.Loadout.WeaponAt(WeaponSlot.Main)));Assert.That(actual.Loadout.WeaponAt(WeaponSlot.Sidearm),Is.EqualTo(soldier.Loadout.WeaponAt(WeaponSlot.Sidearm)));Assert.That(actual.Loadout.Mount,Is.EqualTo(soldier.Loadout.Mount));Assert.That(restored.Soldiers.Definitions.GetRequired(TroopDefinitionId.Create("deli")).AllowsArmor,Is.False);}
        [Test]public void SchemaNineSerialization_IsCanonicalAcrossDefinitionInsertionOrder(){var a=Context(reverse:false);var b=Context(reverse:true);AcquireDeli(a);AcquireDeli(b);var serializer=new CampaignSaveTextSerializer();Assert.That(serializer.Serialize(CampaignSaveMapper.ToSaveData(a.Runtime)),Is.EqualTo(serializer.Serialize(CampaignSaveMapper.ToSaveData(b.Runtime))));}
        [Test]public void MigrationEightToNinePreservesPriorDomainsWithoutInventingSoldiers(){var c=Context();var source=CampaignSaveMapper.ToSaveData(c.Runtime);source.SaveVersion=8;var migrated=new CampaignSaveV8ToV9Migration().Apply(source);Assert.That(migrated.SaveVersion,Is.EqualTo(9));Assert.That(migrated.Armies.Count,Is.EqualTo(source.Armies.Count));Assert.That(migrated.TradeGoods.Count,Is.EqualTo(source.TradeGoods.Count));Assert.That(migrated.Soldiers,Is.Empty);Assert.That(migrated.EquipmentInstances,Is.Empty);}
        [Test]public void HardcodedSchemaEightFixtureMigratesWithoutFakeSoldierState(){const string fixture="FOC_CAMPAIGN_SAVE\nSaveVersion=8\nCampaignId=Y2FtcGFpZ24tbGVnYWN5\nGameVersion=MC4wLjg=\nContentDataVersion=bWlsaXRhcnktMQ==\nWorldSeed=1648\nWorldGenRevision=1\nWorldTime=9\nRngState=123\nRngDrawCount=2\nCharacterCount=0\nCharacterRelationCount=0\nSocialState=AAAAAAAAAAAAAAAA\nReligionState=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\nCityState=AAAAAA==\nEconomyState=AAAAAAAAAAAAAAAAAAAAAA==\nDiplomacyState=AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=\nMilitaryState=AAAAAAAAAAAAAAAA\n";var read=new CampaignSaveTextSerializer().Deserialize(fixture);Assert.That(read.Success,Is.True,read.Error);var migrated=new CampaignSaveV8ToV9Migration().Apply(read.Data!);Assert.That(migrated.SaveVersion,Is.EqualTo(9));Assert.That(migrated.Soldiers,Is.Empty);Assert.That(migrated.EquipmentInstances,Is.Empty);}
        [Test]public void FullMigrationChainReachesNineWithoutFakeSoldiers(){var source=new CampaignSaveData{SaveVersion=1,CampaignId="legacy",GameVersion="0.1",ContentDataVersion="one",WorldSeed=1,RngState=1};var pipeline=new SaveMigrationPipeline(new ISaveMigration[]{new CampaignSaveV1ToV2Migration(),new CampaignSaveV2ToV3Migration(),new CampaignSaveV3ToV4Migration(),new CampaignSaveV4ToV5Migration(),new CampaignSaveV5ToV6Migration(),new CampaignSaveV6ToV7Migration(),new CampaignSaveV7ToV8Migration(),new CampaignSaveV8ToV9Migration()});var result=pipeline.Migrate(source,9);Assert.That(result.Success,Is.True,result.Error);Assert.That(result.Data!.Soldiers,Is.Empty);Assert.That(result.Data.EquipmentInstances,Is.Empty);}
        [Test]public void RuntimeInvariantValidatorAcceptsIntegratedStateAndRejectsMissingUnit(){var c=Context();AcquireDeli(c);Assert.That(new SoldierInvariantValidator().Validate(c.Runtime).IsValid,Is.True);var bad=new CampaignRuntimeState(StableId<CampaignTag>.Create("bad"),"0.8","soldier",1,1,new WorldClock(T(0)),new SeededRandomSource(1),soldiers:c.Runtime.Soldiers);Assert.That(new SoldierInvariantValidator().Validate(bad).IsValid,Is.False);}
        [Test]public void SaveValidatorRejectsDanglingEquipmentAndWrongOwner(){var c=Context();AcquireDeli(c);var data=CampaignSaveMapper.ToSaveData(c.Runtime);data.EquipmentInstances[0].OwnerId="missing-soldier";data.Soldiers[0].Weapons[0].EquipmentInstanceId="missing-equipment";var validation=new CampaignSaveValidator().Validate(data);Assert.That(validation.IsValid,Is.False);Assert.That(validation.Issues.Any(x=>x.Code=="EQUIPMENT_INSTANCE_INVALID"),Is.True);}
        [Test]public void SaveValidatorMutationRiskRejectsWrongSlotAndForbiddenArmor(){var c=Context();AcquireDeli(c);var data=CampaignSaveMapper.ToSaveData(c.Runtime);data.Soldiers.Single().Weapons.Single(x=>x.Slot==(int)WeaponSlot.Main).Slot=(int)WeaponSlot.Sidearm;var armor=new EquipmentInstanceSaveData{EquipmentInstanceId="forbidden-armor",DefinitionKind=(int)EquipmentKind.Armor,DefinitionId="body-armor",OwnerKind=(int)EquipmentOwnerKind.Soldier,OwnerId="soldier-1",AcquisitionKind=(int)EquipmentAcquisitionKind.CityMarket,AcquisitionSourceId="city-home",EconomicGoodId=c.ArmorGood.Value,AcquiredAt=0,QualityCode="workmanship-standard"};data.EquipmentInstances.Add(armor);data.Soldiers.Single().Armor.Add(new ArmorSlotAssignmentSaveData{Slot=(int)ArmorSlot.Body,EquipmentInstanceId=armor.EquipmentInstanceId});var validation=new CampaignSaveValidator().Validate(data);Assert.That(validation.IsValid,Is.False);Assert.That(validation.Issues.Any(x=>x.Code=="SOLDIER_WEAPON_COMPATIBILITY_INVALID"),Is.True);Assert.That(validation.Issues.Any(x=>x.Code=="SOLDIER_ARMOR_FORBIDDEN"),Is.True);}
        [Test]public void DomainBattleAndSoldierRemainPresentationAndUnityFree(){var domain=typeof(SoldierInstance).Assembly;Assert.That(domain.GetTypes().Any(x=>x.Namespace=="FOC.Domain.Battle"),Is.True);Assert.That(domain.GetTypes().Any(x=>x.Name=="VisualSoldier"||x.Namespace!=null&&x.Namespace.Contains("Presentation")),Is.False);Assert.That(domain.GetReferencedAssemblies().Any(x=>x.Name!=null&&x.Name.StartsWith("Unity",StringComparison.Ordinal)),Is.False);Assert.That(typeof(SoldierInstance).GetProperties().Any(x=>x.PropertyType.Name.Contains("GameObject")||x.PropertyType.Name.Contains("Animator")),Is.False);}

        private sealed class Data{public CampaignRuntimeState Runtime=null!;public SoldierEquipmentService Service=null!;public UnitGroupState Unit=null!;public RecruitmentRecord Record=null!;public CityMarketState Market=null!;public TradeGoodId WeaponGood;public TradeGoodId AmmoGood;public TradeGoodId ArmorGood;public TradeGoodId MountGood;public TradeGoodId ShieldGood;}
        private static Data Context(string troop="deli",long headcount=10,bool reverse=false)
        {
            var d=new Data{WeaponGood=TradeGoodId.Create("weapon-good"),AmmoGood=TradeGoodId.Create("ammo-good"),ArmorGood=TradeGoodId.Create("armor-good"),MountGood=TradeGoodId.Create("mount-good"),ShieldGood=TradeGoodId.Create("shield-good")};var goods=new TradeGoodRegistry();var goodDefs=new[]{Good(d.WeaponGood,TradeGoodCategory.Military),Good(d.AmmoGood,TradeGoodCategory.Military),Good(d.ArmorGood,TradeGoodCategory.Military),Good(d.MountGood,TradeGoodCategory.RawMaterial),Good(d.ShieldGood,TradeGoodCategory.Military)};foreach(var g in reverse?goodDefs.Reverse():goodDefs)goods.Add(g);var stock=new CityStockState();foreach(var g in goodDefs)stock.AddInitial(new TradeGoodStock(g.Id,20));d.Market=new CityMarketState(CityId.Create("city-home"),0,stock);var economy=new EconomyState(goods);economy.AddMarket(d.Market);var cities=new CityRegistry();cities.Add(CityTestFactory.State("city-home"));var chars=new CharacterRoster();var officer=CharacterTestFactory.Named("officer");chars.Add(officer);var armyId=ArmyId.Create("army");var org=new OrganizationState(OrganizationId.Create("org"),"Army Organization");var assignment=new AssignmentState(AssignmentId.Create("recruit-authority"),officer.Id,OrganizationBranch.Army,"recruit",AssignmentAuthority.FullAuthority,AssignmentTarget.Army(armyId),AssignmentPresence.RemoteCapable,T(0));org.AddAssignment(assignment);var orgs=new OrganizationRegistry();orgs.Add(org);var source=new RecruitmentSourceState(RecruitmentSourceId.Create("source"),RecruitmentType.Retinue,0,new RecruitmentAuthorityReference(officer.Id,org.Id,assignment.Id));var military=new CampaignMilitaryState();military.RecruitmentSources.Add(source);var army=new ArmyState(armyId,"Army",ArmyOwnerRef.Organization(org.Id),ArmyOwnerRef.Organization(org.Id),ArmyLocation.InCity(CityId.Create("city-home")));military.Armies.Add(army);d.Unit=new UnitGroupState(UnitGroupId.Create("unit"),army.Id,source.Id,troop,headcount);military.RestoreUnit(d.Unit);d.Record=new RecruitmentRecord(RecruitmentRecordId.Create("record"),source.Id,army.Id,d.Unit.Id,headcount,T(0));military.RestoreRecord(d.Record);var soldierState=new SoldierCampaignState();AddDefinitions(soldierState.Definitions,d,reverse);AddExtendedDefinitions(soldierState.Definitions,d,reverse);AddTestTroop(soldierState.Definitions);d.Runtime=new CampaignRuntimeState(StableId<CampaignTag>.Create("campaign"),"0.8","soldier-1",1648,1,new WorldClock(T(0)),new SeededRandomSource(44),chars,orgs,null,null,null,cities,economy,null,military,soldierState);d.Service=new SoldierEquipmentService(d.Runtime);return d;
